    sealed class AddonDragMotion : IUiMotion {
        readonly UiMotionClock clock;readonly Canvas layer;readonly Action finished;Border ghost;double x,y,vx,vy,tx,ty,scale=1,vs;bool direct;long lastMove;
        public bool Active {get{return ghost!=null;}}public Point Position {get{return new Point(x,y);}}
        public AddonDragMotion(UiMotionClock clock,Canvas layer,Action finished){this.clock=clock;this.layer=layer;this.finished=finished;clock.Register(this);}
        public void Begin(Border visual,Point point,bool inherit){double previousX=vx,previousY=vy;Stop();ghost=visual;x=tx=point.X;y=ty=point.Y;vx=inherit?previousX:0;vy=inherit?previousY:0;scale=1;vs=0;direct=true;lastMove=System.Diagnostics.Stopwatch.GetTimestamp();layer.Children.Add(ghost);Draw();clock.Wake(this);}
        public void Track(Point point){if(ghost==null)return;long now=System.Diagnostics.Stopwatch.GetTimestamp();double dt=(now-lastMove)/(double)System.Diagnostics.Stopwatch.Frequency;if(dt>.001){vx=dt<.15?Math.Max(-1800,Math.Min(1800,.35*vx+.65*(point.X-x)/dt)):0;vy=dt<.15?Math.Max(-1800,Math.Min(1800,.35*vy+.65*(point.Y-y)/dt)):0;lastMove=now;}x=point.X;y=point.Y;Draw();clock.Wake(this);}
        public void Land(Point point){if(ghost==null)return;if((System.Diagnostics.Stopwatch.GetTimestamp()-lastMove)/(double)System.Diagnostics.Stopwatch.Frequency>.12)vx=vy=0;direct=false;tx=point.X;ty=point.Y;clock.Wake(this);}
        void Draw(){if(ghost==null)return;Canvas.SetLeft(ghost,x);Canvas.SetTop(ghost,y);ghost.RenderTransform=new ScaleTransform(scale,scale);ghost.RenderTransformOrigin=new Point(.5,.5);}
        public bool Step(double dt,bool animate){if(ghost==null)return false;double target=direct&&animate?1.035:1;if(animate){if(!direct){PlayerSpring.Step(ref x,ref vx,tx,dt,.24,1);PlayerSpring.Step(ref y,ref vy,ty,dt,.24,1);}PlayerSpring.Step(ref scale,ref vs,target,dt,.16,1);}else{if(!direct){x=tx;y=ty;}scale=1;vx=vy=vs=0;}Draw();bool moving=Math.Abs(scale-target)>.001||Math.Abs(vs)>.01||!direct&&(Math.Abs(x-tx)>.03||Math.Abs(y-ty)>.03||Math.Abs(vx)>.05||Math.Abs(vy)>.05);if(!direct&&!moving){Stop();finished();return false;}return moving;}
        public void Stop(){if(ghost!=null)layer.Children.Remove(ghost);ghost=null;clock.Cancel(this);}
        public void Snap(){if(ghost==null)return;if(direct){scale=1;vs=0;Draw();}else{Stop();finished();}}
    }
