        bool BeginAddonTileDrag(int index,Point pointer){var slot=addonDeck.At(index);if(addonReadOnly||slot==null||addonWindow!=null)return false;bool inherit=addonDragMotion.Active&&addonDragVisualBinding==slot.BindingId;var start=inherit?addonDragMotion.Position:AddonSlotRect(index).TopLeft;CancelAddonTileDrag();addonDragSource=index;addonDragBinding=addonDragVisualBinding=slot.BindingId;addonDragGrab=new Point(pointer.X-start.X,pointer.Y-start.Y);addonDragMotion.Begin(AddonGhost(index),start,inherit);addonButtons[index].Opacity=.23;addonTileDragging=true;collapse.Stop();TrackAddonTileDrag(pointer);return true;}
