        bool CompleteAddonTileDrag(bool cancel){if(!addonTileDragging)return false;int source=addonDragSource,target=addonDragTarget;bool valid=!cancel&&target>=0&&target!=source&&addonDeck.At(source)!=null&&addonDeck.At(source).BindingId==addonDragBinding&&!addonReadOnly;addonTileDragging=false;addonDragCandidate=-1;addonDropTarget.Visibility=Visibility.Collapsed;addonDragReleasing=true;try{if(addonDragCaptured!=null&&addonDragCaptured.IsMouseCaptured)addonDragCaptured.ReleaseMouseCapture();}finally{addonDragCaptured=null;addonDragReleasing=false;}
